**Correction to the previous walk-through:** I made two errors. First, the Zab paragraph gave the entry a "zxid 8," which is wrong. A zxid is 64 bits, with the epoch in the high 32 bits and a counter in the low 32 bits, so the entry from the first example would carry epoch 7 in its high bits. Second, I said n2 could not win the election in term 8. That was wrong: n2's last entry (index 43, term 7) is more up to date than n4's (index 42, term 7), so n2 could have won with votes from n3, n4, and n5. The outcome does not change, because entry 43 was never committed and losing it is correct. I have not compiled or run the code below in this session.

# A Runnable Model of Kestrel's Consensus Core

The walk-through described what happens. This section shows it in code: a compact Go model of the Raft-style core that Kestrel's ledger runs on. It covers term-based voting with the voting restriction, log matching with conflict truncation, quorum commit with the current-term rule, and idempotent application of a debit. It is a teaching model, not a production system. It has no disk persistence, no snapshots, no membership change, and no randomized timers. Its transport is an in-memory cut matrix, so a test can partition the cluster exactly where it wants.

The code lives in two files in one package. `kestrel.go` holds the protocol and `failover_test.go` holds the scenario.

```go
// kestrel.go
package kestrel

import (
	"errors"
	"sort"
)

// Kestrel runs 5 nodes across 3 regions, so a quorum is any 3.
const Quorum = 3

var (
	ErrNotLeader    = errors.New("not leader")
	ErrNotCommitted = errors.New("not committed")
	ErrInsufficient = errors.New("insufficient funds")
)

type Role int

const (
	Follower Role = iota
	Candidate
	Leader
)

// Command is a ledger operation. IdemKey makes client retries safe.
// An empty IdemKey marks a no-op entry.
type Command struct {
	IdemKey string
	Account string
	Amount  int64 // negative for a debit
}

type Entry struct {
	Term  uint64
	Index uint64
	Cmd   Command
}

type Result struct {
	Balance int64
	Err     error
}

type Node struct {
	ID          int
	Role        Role
	CurrentTerm uint64
	VotedFor    int     // -1 means no vote cast in CurrentTerm
	log         []Entry // log[0] is a sentinel with Index 0
	CommitIndex uint64
	LastApplied uint64

	balances   map[string]int64
	results    map[string]Result // applied outcome per IdemKey
	nextIndex  map[int]uint64    // leader only
	matchIndex map[int]uint64    // leader only
}

func newNode(id int) *Node {
	return &Node{
		ID:         id,
		VotedFor:   -1,
		log:        []Entry{{}},
		balances:   map[string]int64{},
		results:    map[string]Result{},
		nextIndex:  map[int]uint64{},
		matchIndex: map[int]uint64{},
	}
}

func (n *Node) lastIndexTerm() (uint64, uint64) {
	e := n.log[len(n.log)-1]
	return e.Index, e.Term
}

// observeTerm steps down when a higher term appears. In a real node,
// CurrentTerm and VotedFor must be fsynced before any reply leaves.
func (n *Node) observeTerm(term uint64) {
	if term > n.CurrentTerm {
		n.CurrentTerm = term
		n.VotedFor = -1
		n.Role = Follower
	}
}

// appendLocal adds a command to this leader's own log.
func (n *Node) appendLocal(cmd Command) uint64 {
	idx, _ := n.lastIndexTerm()
	n.log = append(n.log, Entry{Term: n.CurrentTerm, Index: idx + 1, Cmd: cmd})
	n.matchIndex[n.ID] = idx + 1
	return idx + 1
}

type VoteReq struct {
	Term                  uint64
	Candidate             int
	LastIndex, LastTerm   uint64
}

type VoteResp struct {
	Term    uint64
	Granted bool
}

// HandleVote applies the voting restriction: grant only to a candidate
// whose log is at least as up to date as ours.
func (n *Node) HandleVote(req VoteReq) VoteResp {
	n.observeTerm(req.Term)
	if req.Term < n.CurrentTerm {
		return VoteResp{Term: n.CurrentTerm}
	}
	li, lt := n.lastIndexTerm()
	upToDate := req.LastTerm > lt || (req.LastTerm == lt && req.LastIndex >= li)
	if (n.VotedFor == -1 || n.VotedFor == req.Candidate) && upToDate {
		n.VotedFor = req.Candidate
		return VoteResp{Term: n.CurrentTerm, Granted: true}
	}
	return VoteResp{Term: n.CurrentTerm}
}

type AppendReq struct {
	Term         uint64
	Leader       int
	PrevIndex    uint64
	PrevTerm     uint64
	Entries      []Entry
	LeaderCommit uint64
}

type AppendResp struct {
	Term       uint64
	Success    bool
	MatchIndex uint64
}

// HandleAppend enforces log matching and truncates conflicting suffixes.
func (n *Node) HandleAppend(req AppendReq) AppendResp {
	n.observeTerm(req.Term)
	if req.Term < n.CurrentTerm {
		return AppendResp{Term: n.CurrentTerm}
	}
	n.Role = Follower
	if req.PrevIndex >= uint64(len(n.log)) || n.log[req.PrevIndex].Term != req.PrevTerm {
		return AppendResp{Term: n.CurrentTerm}
	}
	for _, e := range req.Entries {
		if e.Index < uint64(len(n.log)) {
			if n.log[e.Index].Term == e.Term {
				continue
			}
			n.log = n.log[:e.Index] // conflicting suffix is discarded
		}
		n.log = append(n.log, e)
	}
	last := req.PrevIndex + uint64(len(req.Entries))
	if req.LeaderCommit > n.CommitIndex {
		n.CommitIndex = min(req.LeaderCommit, last)
		n.applyCommitted()
	}
	return AppendResp{Term: n.CurrentTerm, Success: true, MatchIndex: last}
}

// applyCommitted runs the state machine. Every node applies the same
// entries in the same order, so every node reaches the same balances.
func (n *Node) applyCommitted() {
	for n.LastApplied < n.CommitIndex {
		n.LastApplied++
		cmd := n.log[n.LastApplied].Cmd
		if cmd.IdemKey == "" {
			continue // no-op
		}
		if _, done := n.results[cmd.IdemKey]; done {
			continue // duplicate submission: keep the first outcome
		}
		if n.balances[cmd.Account]+cmd.Amount < 0 {
			n.results[cmd.IdemKey] = Result{Balance: n.balances[cmd.Account], Err: ErrInsufficient}
			continue
		}
		n.balances[cmd.Account] += cmd.Amount
		n.results[cmd.IdemKey] = Result{Balance: n.balances[cmd.Account]}
	}
}

// advanceCommit commits an index only when a quorum stores it and it
// belongs to the leader's current term.
func (n *Node) advanceCommit() {
	idxs := make([]uint64, 0, len(n.matchIndex))
	for _, m := range n.matchIndex {
		idxs = append(idxs, m)
	}
	sort.Slice(idxs, func(i, j int) bool { return idxs[i] > idxs[j] })
	candidate := idxs[Quorum-1]
	if candidate > n.CommitIndex && n.log[candidate].Term == n.CurrentTerm {
		n.CommitIndex = candidate
		n.applyCommitted()
	}
}

// Cluster is an in-memory transport with a settable cut matrix.
type Cluster struct {
	Nodes []*Node
	cut   map[[2]int]bool
}

func NewCluster(size int) *Cluster {
	c := &Cluster{cut: map[[2]int]bool{}}
	for i := 0; i < size; i++ {
		c.Nodes = append(c.Nodes, newNode(i))
	}
	return c
}

func (c *Cluster) Cut(a, b int) {
	c.cut[[2]int{a, b}] = true
	c.cut[[2]int{b, a}] = true
}

func (c *Cluster) connected(a, b int) bool {
	return !c.cut[[2]int{a, b}]
}

// Campaign runs one election for node id. A winner appends a no-op in
// its new term, which lets earlier entries commit under the current-term rule.
func (c *Cluster) Campaign(id int) bool {
	cand := c.Nodes[id]
	cand.CurrentTerm++
	cand.Role = Candidate
	cand.VotedFor = id
	li, lt := cand.lastIndexTerm()
	votes := 1
	for _, p := range c.Nodes {
		if p.ID == id || !c.connected(id, p.ID) {
			continue
		}
		resp := p.HandleVote(VoteReq{Term: cand.CurrentTerm, Candidate: id, LastIndex: li, LastTerm: lt})
		if resp.Term > cand.CurrentTerm {
			cand.observeTerm(resp.Term)
			return false
		}
		if resp.Granted {
			votes++
		}
	}
	if votes < Quorum {
		cand.Role = Follower
		return false
	}
	cand.Role = Leader
	for _, p := range c.Nodes {
		cand.nextIndex[p.ID] = uint64(len(cand.log))
		cand.matchIndex[p.ID] = 0
	}
	cand.appendLocal(Command{})
	c.replicate(id)
	return true
}

// Propose is the client entry point. A retry with a known IdemKey
// returns the earlier outcome without appending anything.
func (c *Cluster) Propose(leader int, cmd Command) (Result, error) {
	l := c.Nodes[leader]
	if l.Role != Leader {
		return Result{}, ErrNotLeader
	}
	if r, ok := l.results[cmd.IdemKey]; ok {
		return r, nil
	}
	idx := l.appendLocal(cmd)
	c.replicate(leader)
	if l.CommitIndex < idx {
		return Result{}, ErrNotCommitted
	}
	return l.results[cmd.IdemKey], nil
}

// replicate sends each reachable follower its missing suffix, backing
// nextIndex up one step per rejection until the logs match.
func (c *Cluster) replicate(leaderID int) {
	l := c.Nodes[leaderID]
	for _, p := range c.Nodes {
		if p.ID == leaderID || !c.connected(leaderID, p.ID) {
			continue
		}
		next := l.nextIndex[p.ID]
		for {
			req := AppendReq{
				Term:         l.CurrentTerm,
				Leader:       leaderID,
				PrevIndex:    next - 1,
				PrevTerm:     l.log[next-1].Term,
				Entries:      l.log[next:],
				LeaderCommit: l.CommitIndex,
			}
			resp := p.HandleAppend(req)
			if resp.Term > l.CurrentTerm {
				l.observeTerm(resp.Term)
				return
			}
			if resp.Success {
				l.nextIndex[p.ID] = resp.MatchIndex + 1
				l.matchIndex[p.ID] = resp.MatchIndex
				break
			}
			if next <= 1 {
				break
			}
			next--
			l.nextIndex[p.ID] = next
		}
	}
	l.advanceCommit()
}
```

```go
// failover_test.go
package kestrel

import "testing"

func TestFailoverPreservesCommittedDebit(t *testing.T) {
	c := NewCluster(5)
	if !c.Campaign(0) {
		t.Fatal("node 0 should win term 1")
	}
	c.Propose(0, Command{IdemKey: "dep-1", Account: "M-2041", Amount: 1000})
	c.Propose(0, Command{IdemKey: "pay-88713", Account: "M-2041", Amount: -100})

	// Region A's leader is cut off from the other 4 nodes.
	for i := 1; i < 5; i++ {
		c.Cut(0, i)
	}
	if !c.Campaign(1) {
		t.Fatal("node 1 should win term 2")
	}

	// The client retries after a timeout with the same key.
	r, err := c.Propose(1, Command{IdemKey: "pay-88713", Account: "M-2041", Amount: -100})
	if err != nil || r.Balance != 900 {
		t.Fatalf("retry: balance=%d err=%v, want 900 and nil", r.Balance, err)
	}

	// The stale leader cannot commit anything while cut off.
	_, err = c.Propose(0, Command{IdemKey: "pay-99999", Account: "M-2041", Amount: -50})
	if err != ErrNotCommitted {
		t.Fatalf("stale leader: err=%v, want ErrNotCommitted", err)
	}
}
```

## How the Code Maps to the Protocol

**Voting restriction.** `HandleVote` grants a vote only when the candidate's last term is higher, or the terms are equal and the candidate's index is at least as high. This is the reason node 1 could win term 2: its log matches node 0's committed history, and the 4 nodes that voted for it held the debit.

**Term persistence.** `observeTerm` is where a term change happens, and the comment marks the one thing the model omits. A real node must write `CurrentTerm` and `VotedFor` to stable storage before replying. The model keeps them in memory, so it cannot show the crash-and-revote failure from the trade-offs section, but the code marks where the fsync belongs.

**Log matching and truncation.** `HandleAppend` rejects a request whose `PrevIndex` entry has a different term. When an incoming entry conflicts with an existing one, the follower truncates its suffix from that point. The leader's `replicate` loop backs `nextIndex` up one step per rejection until the logs agree, which is the repair path from the walk-through.

**Current-term commit rule.** `advanceCommit` finds the quorum-th highest `matchIndex` and commits it only when the entry's term equals `CurrentTerm`. Together with the no-op appended in `Campaign`, this is what makes older entries safe to commit. Without the rule, an entry from term 1 could be counted toward a quorum and later overwritten by a new leader.

**Idempotent apply.** `applyCommitted` runs the same deterministic function on every node. Duplicate `IdemKey` values are skipped, and the first outcome is kept. The debit that was retried in the test returns balance 900 and is never applied twice. Overdraft is also decided during apply, so every node reaches the same rejection.

**What the test shows.** The debit committed on a quorum before the partition, so it survives the election of node 1. The retry returns the stored result rather than appending a second entry. The old leader's proposal cannot reach a quorum and is reported as not committed, so the client learns it is unknown and must not assume success.

## Where the Model Stops

Production consensus needs several things this model leaves out. Persistence must be fsynced. Election timers must be randomized and sized from measured cross-region latency. Snapshots prevent the log from growing without bound. Membership changes need the joint-consensus or single-step procedure from the trade-offs section. Finally, the transport must handle loss, duplication, and reordering, which this in-memory matrix never produces. Each omission is a place where a real Kestrel deployment would need its own tests before it could be trusted with payments.

Key takeaway: For Kestrel, the safety of a debit comes from three checks working together in code, the voting restriction, log matching with truncation, and the current-term commit rule, and the idempotency key keeps a client's retry from posting the debit twice.

# Common Mistakes With Consensus Algorithms, and How to Catch Them

Most consensus failures in production are not novel. They are the same handful of errors, made by teams that understood the protocol well enough to implement it and not well enough to see where their implementation departed from it. The mistakes below recur across Raft, Paxos, and Zab deployments. For each one we give the symptom, a Kestrel-flavored story, and a detection method. Kestrel is our payments ledger on 5 nodes across 3 regions.

The detection methods matter more than the list. Each mistake is easy to make in code review and hard to see in ordinary operation, because the bad behavior appears only under partition, crash, or clock skew. The recurring lesson is that you must test the failure, not the happy path.

## Mistake 1: Acknowledging Before Commit

The most damaging mistake is returning success to the client when the leader has written the entry locally, before a quorum has stored it. It looks like a performance optimization, and the code often passes every test that runs on a healthy cluster.

**Symptom.** Acknowledged payments disappear after a leader failure. The client has a success response and the ledger has no entry.

**Kestrel story.** A team moved the commit wait out of the request path to reduce tail latency, returning success after the local fsync. During a leader crash, 14 acknowledged debits were never on a quorum. The new leader did not have them, and the merchant's customers were charged at the terminal but never debited on the ledger.

**Detection.** Write a test that acknowledges a command, crashes the leader immediately afterward, and asserts that the command is present on a quorum of nodes. The model in the previous section makes the rule explicit: `Propose` returns success only when `CommitIndex` has reached the new entry. A review check can enforce it by requiring that every success path in the request handler be dominated by a commit check.

## Mistake 2: Replying Before Persisting Term and Vote

A node that grants a vote, or accepts a term, must have that decision on stable storage before the reply leaves. Otherwise, a crash and restart can make the node vote again in the same term, and two candidates can each collect a quorum.

**Symptom.** Two leaders in the same term, visible only in logs after an unexplained restart.

**Kestrel story.** A storage controller acknowledged fsync from its write cache before data reached media. After a power loss, a node came back with a forgotten vote. The cluster avoided two leaders only because the other votes happened to fall the right way, which was luck.

**Detection.** Use a storage fault harness that drops writes not yet flushed at a simulated power cut, then assert that a restarted node never grants a second vote in a term it already voted in. Verify fsync behavior at commissioning time, by checking that a write acknowledged by the device survives a controlled power cut, not by trusting the controller's settings.

```go
// persistVote must return before the vote reply is sent.
// A test double records calls so the harness can assert ordering.
func (s *Store) persistVote(term uint64, votedFor int) error {
	if err := s.write(term, votedFor); err != nil {
		return err
	}
	return s.fsync() // the reply is sent only after this returns nil
}
```

## Mistake 3: Counting Old-Term Entries Toward Commitment

Raft forbids committing an entry from an earlier term by counting replicas on a quorum. A team that implements commitment as "the quorum-th highest index" without the current-term check will commit entries that a later leader can overwrite.

**Symptom.** A committed-looking entry disappears after a leader change, and clients that saw it acknowledged are now inconsistent with the ledger.

**Kestrel story.** The Raft paper's Figure 8 scenario reproduces this exactly. A leader copies an entry from term 2 to a majority, crashes, and a term-4 leader overwrites it, even though the entry was on a majority. The team had written the commit rule without the term check, and their randomized testing had never produced the sequence.

**Detection.** Write a property test that generates leader-failure sequences, not just single failures. The model's `advanceCommit` guard, `n.log[candidate].Term == n.CurrentTerm`, is the line to test, and removing it should make a test fail. Mutation testing is the practical check: if deleting the guard does not break any test, the test suite does not cover this rule.

## Mistake 4: Election Timeouts Sized for the Wrong Network

An election timeout that is shorter than the normal worst-case network delay causes repeated leader changes. Each change pauses commits while the new leader repairs follower logs, and clients retry into the pause.

**Symptom.** Frequent elections in the logs, commit latency spikes that line up with network jitter, and client timeouts that rise during routine provider events.

**Kestrel story.** The election timeout was tuned on a single-region test cluster. Cross-region latency spikes of 200 to 300 milliseconds triggered elections every few minutes. Pre-vote was absent, so a node rejoining after a partition disrupted a healthy leader.

**Detection.** Monitor elections per hour as a first-class metric, and alert when it exceeds a baseline. In staging, inject latency between regions at the 99th percentile of production measurements, and assert that the leader does not change. Size the timeout from measured round-trip percentiles, and enable pre-vote so that a partitioned node cannot force a term increase.

## Mistake 5: Unsafe Membership Changes

Changing the node set is where consensus implementations most often break safety. Two configurations can each form an independent quorum during the transition, and the old and new majorities may not overlap.

**Symptom.** Two leaders accept writes during a membership change, usually after a partition coincides with the change.

**Kestrel story.** An operator replaced a node in region C by adding the new node and removing the old one as two separate manual steps. A partition landed between them. Both sides elected leaders, both accepted debits, and two payments needed manual reversal.

**Detection.** Use only the protocol's supported membership change path, and never sequence it by hand. Before any change, run a staging test that cuts the network between regions at each intermediate step and asserts that at most one leader per term exists. A check that is easy to script is to compute, for each intermediate configuration, whether any two possible quorums can be disjoint.

## Mistake 6: Leases Without Bounded Clock Error

Leader leases let a leader serve reads locally, but they are only correct if the leader's clock and the followers' clocks agree within a known bound. Teams often assume time sync is "good enough" and skip the bound.

**Symptom.** Stale reads that a linearizability checker can reproduce, usually around leader pauses or time-sync adjustments.

**Kestrel story.** A leader stalled on a long garbage-collection pause, and its clock was ahead because of a misconfigured time daemon. It served balance reads after a new leader had committed a debit, so a customer saw a balance higher than their real funds for about 400 milliseconds.

**Detection.** Record concurrent client histories and run them through a linearizability checker, such as Porcupine, against the read path. Inject clock skew and pauses in tests. Use ReadIndex for balance reads unless the lease's skew bound is measured and enforced.

## Mistake 7: Retries Without Idempotency

Consensus gives a leader an unambiguous answer about a committed entry only if the client can get that answer. A client that times out does not know whether its command committed, and a retry without an idempotency key can post the command twice.

**Symptom.** Duplicate debits, usually visible only in reconciliation against external settlement files.

**Kestrel story.** A payment service retried on timeout without a key. A leader failover happened during the original request, and the original entry had committed. The ledger posted the debit twice.

**Detection.** Every command must carry an idempotency key that the state machine checks at apply time, as in the model's `applyCommitted`. Reconcile the ledger daily against settlement and treat any duplicate `IdemKey` in the applied state as a defect. The check is a query, and it should run continuously, not only at month-end.

## Mistake 8: Incomplete Recovery in Hand-Built Paxos or Zab

Single-decree Paxos is simple, but multi-decree recovery and snapshot handling are not. Teams that build on the basic paper often omit the step where a new leader must propose the highest-numbered accepted value for each open slot, or the rule that a recovering node must not install a stale snapshot.

**Symptom.** Nodes whose applied logs disagree after randomized partitions, with no obvious single cause.

**Kestrel story.** A Paxos-based prototype skipped recovery of open slots. A leader change caused two nodes to apply different values for the same slot. Nothing failed loudly, and the divergence appeared only in the reconciliation job.

**Detection.** Compare applied logs across all nodes after randomized partition runs. The check is a prefix-agreement assertion, and it catches divergence the moment it happens.

```go
// CheckPrefixAgreement asserts that every pair of nodes agrees on every
// entry both have applied. Run it after each randomized partition scenario.
func CheckPrefixAgreement(nodes []*Node) error {
	ref := nodes[0]
	for _, n := range nodes[1:] {
		limit := min(n.LastApplied, ref.LastApplied)
		for i := uint64(1); i <= limit; i++ {
			if n.log[i].Term != ref.log[i].Term || n.log[i].Cmd != ref.log[i].Cmd {
				return fmt.Errorf("node %d and node %d disagree at index %d", n.ID, ref.ID, i)
			}
		}
	}
	return nil
}
```

For protocol-level changes, model-check the algorithm in TLA+ before implementing it. A small spec with the recovery step is cheap to write and catches gaps the paper leaves open.

## Mistake 9: Quorum Placement That Ignores Failure Domains

Consensus tolerates failures only in the sense the placement allows. A layout that puts a majority of nodes in one failure domain fails when that domain fails, whatever the node count says.

**Symptom.** A single-region outage stops all writes, even though the cluster has enough nodes overall.

**Kestrel story.** An early layout placed 3 of Kestrel's 5 nodes in one region. Losing that region stopped every payment.

**Detection.** Validate placement as code. The check below reports any single-region loss that leaves fewer nodes than a quorum, and it should run in the deployment pipeline before any node is added.

```go
// SurvivesRegionLoss returns an error if losing any one region leaves
// fewer nodes than a quorum. regionOf[i] is the region of node i.
func SurvivesRegionLoss(regionOf []string, quorum int) error {
	counts := map[string]int{}
	for _, r := range regionOf {
		counts[r]++
	}
	for region, lost := range counts {
		if len(regionOf)-lost < quorum {
			return fmt.Errorf("losing %s leaves %d nodes, need %d", region, len(regionOf)-lost, quorum)
		}
	}
	return nil
}
```

## Putting the Checks Together

These mistakes share a pattern. Each passes the happy-path test suite, and each surfaces only when a failure lines up with a specific ordering of events. A useful practice is to map each mistake to a test in the release pipeline, and to make the pipeline fail when a test is missing. For Kestrel, that means fault injection for crashes, partitions, storage loss, and clock skew, linearizability checks on reads, prefix agreement after every partition scenario, placement validation on every topology change, and reconciliation of duplicate idempotency keys against settlement.

Key takeaway: The consensus bugs that cost real money are the ones that pass a healthy-cluster test, so for Kestrel every mistake above needs a fault-injection or invariant check that would fail if the bug were reintroduced.

I have not compiled or run this code in this session. The example is a standalone model, not Kestrel's production code.

# A Runnable Model of CAP Decisions in Kestrel

The worked example showed the decisions. This section puts them in code: a routing policy that decides per operation what a node may do during a partition, a session type that enforces a read-your-writes floor, a version guard for refunds, a brute-force linearizability checker for small client histories, and tests that tie the three together. The file is one package, `kestrel`, with two source files: `consistency.go` for the model and `consistency_test.go` for the scenarios.

## consistency.go

```go
// consistency.go
package kestrel

import "errors"

var (
	ErrInsufficient  = errors.New("insufficient funds")
	ErrStaleDecision = errors.New("decision read a stale version")
)

// OpKind names the purpose of an operation. The purpose, not the node,
// determines the consistency model it needs.
type OpKind int

const (
	WriteCommit OpKind = iota // money movement: needs a quorum
	StrongRead                // authorization: linearizable, needs a quorum
	SessionRead               // history view: must reach the client's floor
	StaleRead                 // display only: local state, labeled as stale
)

// Outcome is what a node may do with an operation on its side of a partition.
type Outcome int

const (
	Commit Outcome = iota
	Serve
	ServeStale
	Refuse
	Reroute
)

var outcomeNames = [...]string{"Commit", "Serve", "ServeStale", "Refuse", "Reroute"}

func (o Outcome) String() string { return outcomeNames[o] }

// NodeView is what one node knows about its side of the partition.
type NodeView struct {
	HasQuorum    bool
	AppliedIndex uint64
	Balance      int64
}

// Op is a request with the floor a session requires, if any.
type Op struct {
	Kind  OpKind
	Floor uint64
}

// Route is the CAP decision. It returns what this node may do for this
// operation. The partition behavior is chosen per operation kind, so one
// partition can refuse a payment and still answer a display request.
func Route(op Op, v NodeView) Outcome {
	switch op.Kind {
	case WriteCommit:
		if !v.HasQuorum {
			return Refuse // a minority commit would diverge from the majority
		}
		return Commit
	case StrongRead:
		if !v.HasQuorum {
			return Refuse // a local answer could approve an overdraft
		}
		return Serve
	case SessionRead:
		if v.AppliedIndex < op.Floor {
			return Reroute // this node is behind what the client has seen
		}
		return Serve
	case StaleRead:
		return ServeStale
	}
	return Refuse
}

// Session carries the highest commit index this client has observed.
// Every acknowledged write and every served read raises the floor.
type Session struct {
	Floor uint64
}

// Observe raises the floor. It never lowers it, which is what keeps the
// client's view from moving backward.
func (s *Session) Observe(index uint64) {
	if index > s.Floor {
		s.Floor = index
	}
}

// Account is the state a money decision reads. Version increases on every commit.
type Account struct {
	Balance int64
	Version uint64
}

// Refund applies only if the account is still at the version the decision
// read. A decision made on a stale read is rejected, never silently applied.
func (a *Account) Refund(asOf uint64, amount int64) error {
	if a.Version != asOf {
		return ErrStaleDecision
	}
	if a.Balance < amount {
		return ErrInsufficient
	}
	a.Balance -= amount
	a.Version++
	return nil
}

// Event is one completed client operation, timed by the client's clock.
// A write sets Value to the new balance. A read sets Value to what it returned.
type Event struct {
	Start, End int64
	Write      bool
	Value      int64
}

// IsLinearizable reports whether some ordering of the events exists that
// (a) respects real time, so an event that ended before another started
// comes first, and (b) makes every read return the value of the latest
// preceding write. The search is exponential, which is fine for the
// small histories used in tests.
func IsLinearizable(h []Event, initial int64) bool {
	return search(h, make([]bool, len(h)), initial)
}

func search(h []Event, used []bool, state int64) bool {
	remaining := false
	for i := range h {
		if used[i] {
			continue
		}
		remaining = true
		if !mayGoNext(h, used, i) {
			continue
		}
		next := state
		if h[i].Write {
			next = h[i].Value
		} else if h[i].Value != state {
			continue // this read cannot be placed here
		}
		used[i] = true
		ok := search(h, used, next)
		used[i] = false
		if ok {
			return true
		}
	}
	return !remaining
}

// mayGoNext is the real-time rule: no unplaced event may have finished
// before event i started.
func mayGoNext(h []Event, used []bool, i int) bool {
	for j := range h {
		if j != i && !used[j] && h[j].End < h[i].Start {
			return false
		}
	}
	return true
}
