## replication.go

```go
// replication.go
package kestrel

import (
	"errors"
	"time"
)

var (
	ErrFenced      = errors.New("write rejected: fencing token is older than the fence")
	ErrUnreachable = errors.New("node unreachable")
	ErrNoQuorum    = errors.New("no quorum acknowledgment")
	ErrCopyStale   = errors.New("copy is beyond its freshness bound")
	ErrVersion     = errors.New("version conflict: reread and reapply")
)

// Entry is one ledger write. Token is the fencing token of the authority
// that created it. AckedAt is the authority's clock when the write reached quorum.
type Entry struct {
	Index   uint64
	Token   uint64
	Data    string
	AckedAt time.Time
}

// Node is one node's durable state: the highest token it has fenced to,
// and the entries it has accepted.
type Node struct {
	ID       int
	Down     bool
	maxToken uint64
	entries  []Entry
}

// Fence raises the node's token floor. Once fenced, a node rejects any
// authority holding an older token, even if that authority is still running.
func (n *Node) Fence(token uint64) error {
	if n.Down {
		return ErrUnreachable
	}
	if token > n.maxToken {
		n.maxToken = token
	}
	return nil
}

// Accept stores an entry only if its token is not older than the fence.
func (n *Node) Accept(e Entry) error {
	if n.Down {
		return ErrUnreachable
	}
	if e.Token < n.maxToken {
		return ErrFenced
	}
	n.maxToken = e.Token
	n.entries = append(n.entries, e)
	return nil
}

// Applied returns the highest index this node holds.
func (n *Node) Applied() uint64 {
	if len(n.entries) == 0 {
		return 0
	}
	return n.entries[len(n.entries)-1].Index
}

// Authority is the node set's single writer for one token. Writes are
// synchronous to Quorum nodes and asynchronous to every copy in Async.
type Authority struct {
	Token  uint64
	Nodes  []*Node
	Quorum int
	Async  []*AsyncCopy
	Now    func() time.Time
	next   uint64
}

// WriteSync acknowledges only after Quorum nodes accept the entry. Each
// acknowledged entry is queued for every async copy, which receives it later.
func (a *Authority) WriteSync(data string) (uint64, error) {
	a.next++
	e := Entry{Index: a.next, Token: a.Token, Data: data}
	acks := 0
	for _, n := range a.Nodes {
		if n.Accept(e) == nil {
			acks++
		}
	}
	if acks < a.Quorum {
		return 0, ErrNoQuorum
	}
	e.AckedAt = a.Now()
	for _, c := range a.Async {
		c.queue = append(c.queue, e)
	}
	return e.Index, nil
}

// Promote fences a quorum of nodes at a new token and returns an authority
// that continues from the most advanced fenced node.
func Promote(token uint64, nodes []*Node, quorum int, now func() time.Time) (*Authority, error) {
	var fenced []*Node
	for _, n := range nodes {
		if n.Fence(token) == nil {
			fenced = append(fenced, n)
		}
	}
	if len(fenced) < quorum {
		return nil, ErrNoQuorum
	}
	var best uint64
	for _, n := range fenced {
		if n.Applied() > best {
			best = n.Applied()
		}
	}
	return &Authority{Token: token, Nodes: nodes, Quorum: quorum, Now: now, next: best}, nil
}

// AsyncCopy receives entries after the authority has acknowledged them.
// Its lag is the age of the oldest entry it has not yet received.
type AsyncCopy struct {
	Node
	queue []Entry
	Bound time.Duration
	Now   func() time.Time
}

// Lag is the current recovery point for this copy: if the authority were
// lost right now, acknowledged entries newer than the copy would be lost.
func (c *AsyncCopy) Lag() time.Duration {
	if len(c.queue) == 0 {
		return 0
	}
	return c.Now().Sub(c.queue[0].AckedAt)
}

// Ship delivers up to n queued entries. Withholding Ship models lag.
func (c *AsyncCopy) Ship(n int) error {
	for ; n > 0 && len(c.queue) > 0; n-- {
		if err := c.Accept(c.queue[0]); err != nil {
			return err
		}
		c.queue = c.queue[1:]
	}
	return nil
}

// Read serves a position only while the copy is within its freshness bound.
func (c *AsyncCopy) Read() (uint64, error) {
	if c.Lag() > c.Bound {
		return 0, ErrCopyStale
	}
	return c.Applied(), nil
}

// Config is a low-rate, single-writer value protected by a version check.
type Config struct {
	Value   string
	Version uint64
}

// Write applies only if the caller read the current version. A concurrent
// edit is rejected and must be reread, never silently overwritten.
func (c *Config) Write(expected uint64, value string) error {
	if c.Version != expected {
		return ErrVersion
	}
	c.Value = value
	c.Version++
	return nil
}
```

