```go
// replication_test.go
package kestrel

import (
	"testing"
	"time"
)

type fakeClock struct{ t time.Time }

func (c *fakeClock) now() time.Time { return c.t }

func newNodes(n int) []*Node {
	nodes := make([]*Node, n)
	for i := range nodes {
		nodes[i] = &Node{ID: i}
	}
	return nodes
}

// The ledger survives the loss of region B (nodes 2 and 3), because every
// acknowledged entry sits on a quorum that includes a survivor.
func TestSyncWriteSurvivesRegionLoss(t *testing.T) {
	clk := &fakeClock{t: time.Unix(0, 0)}
	nodes := newNodes(5)
	a := &Authority{Token: 1, Nodes: nodes, Quorum: 3, Now: clk.now}

	if _, err := a.WriteSync("pay-1"); err != nil {
		t.Fatal(err)
	}
	nodes[2].Down, nodes[3].Down = true, true
	if idx, err := a.WriteSync("pay-2"); err != nil || idx != 2 {
		t.Fatalf("write during outage: idx=%d err=%v", idx, err)
	}

	b, err := Promote(2, nodes, 3, clk.now)
	if err != nil {
		t.Fatal(err)
	}
	if idx, err := b.WriteSync("pay-3"); err != nil || idx != 3 {
		t.Fatalf("write after promotion: idx=%d err=%v, want 3", idx, err)
	}
}

// A deposed authority is rejected by the fence, even though it still holds
// a quorum-sized set of nodes that it believes are its own.
func TestFencedAuthorityIsRejected(t *testing.T) {
	clk := &fakeClock{t: time.Unix(0, 0)}
	nodes := newNodes(5)
	old := &Authority{Token: 1, Nodes: nodes, Quorum: 3, Now: clk.now}
	if _, err := old.WriteSync("pay-1"); err != nil {
		t.Fatal(err)
	}
	if _, err := Promote(2, nodes, 3, clk.now); err != nil {
		t.Fatal(err)
	}
	if _, err := old.WriteSync("stale"); err != ErrNoQuorum {
		t.Fatalf("stale authority: err=%v, want ErrNoQuorum", err)
	}
}

// The archive's lag is its recovery point, and its read path refuses to
// serve once that lag exceeds the bound.
func TestAsyncCopyLagIsRecoveryPoint(t *testing.T) {
	t0 := time.Unix(0, 0)
	clk := &fakeClock{t: t0}
	archive := &AsyncCopy{Node: Node{ID: 9}, Bound: 5 * time.Second, Now: clk.now}
	a := &Authority{Token: 1, Nodes: newNodes(5), Quorum: 3, Async: []*AsyncCopy{archive}, Now: clk.now}

	if _, err := a.WriteSync("pay-1"); err != nil {
		t.Fatal(err)
	}
	clk.t = t0.Add(10 * time.Second)
	if _, err := a.WriteSync("pay-2"); err != nil {
		t.Fatal(err)
	}

	clk.t = t0.Add(15 * time.Second)
	if lag := archive.Lag(); lag != 15*time.Second {
		t.Fatalf("lag = %v, want 15s", lag)
	}
	if _, err := archive.Read(); err != ErrCopyStale {
		t.Fatalf("read at 15s lag: err=%v, want ErrCopyStale", err)
	}

	if err := archive.Ship(1); err != nil {
		t.Fatal(err)
	}
	if lag := archive.Lag(); lag != 5*time.Second {
		t.Fatalf("lag after shipping one entry = %v, want 5s", lag)
	}
	if idx, err := archive.Read(); err != nil || idx != 1 {
		t.Fatalf("read within bound: idx=%d err=%v, want 1", idx, err)
	}
}

// Two administrators read version 14. The first write wins, and the second
// is rejected rather than overwriting it.
func TestConfigRejectsConcurrentEdit(t *testing.T) {
	cfg := &Config{Value: "acct-A", Version: 14}
	if err := cfg.Write(14, "acct-B"); err != nil {
		t.Fatal(err)
	}
	if err := cfg.Write(14, "acct-C"); err != ErrVersion {
		t.Fatalf("concurrent edit: err=%v, want ErrVersion", err)
	}
	if cfg.Value != "acct-B" || cfg.Version != 15 {
		t.Fatalf("value=%q version=%d, want acct-B and 15", cfg.Value, cfg.Version)
	}
}
