## sharding.go

```go
// sharding.go
package kestrel

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"hash/fnv"
	"sort"
)

// SlotCount is small so the model stays readable. A production ledger
// would use far more slots, so that one slot is a small share of load.
const SlotCount = 16

var (
	ErrWrongGroup     = errors.New("slot not owned by this group")
	ErrFrozen         = errors.New("slot frozen for a move")
	ErrStaleRouting   = errors.New("client directory version is behind")
	ErrUnavailable    = errors.New("group unavailable")
	ErrInsufficient   = errors.New("insufficient funds")
	ErrMoved          = errors.New("source changed after the fence")
	ErrDigestMismatch = errors.New("digest mismatch: source stays frozen")
)

// SlotOf maps an account to a slot with a stable hash. The hash never
// changes, so an account's slot is the same for the life of the ledger.
func SlotOf(account string) uint32 {
	h := fnv.New32a()
	h.Write([]byte(account))
	return h.Sum32() % SlotCount
}

// Directory is the authoritative slot-to-group mapping. Every change
// advances Version, so routing can be checked against it.
type Directory struct {
	Version uint64
	Owner   [SlotCount]string
}

// SlotState is a group's state for a slot it holds.
type SlotState int

const (
	Owned SlotState = iota + 1
	Frozen
)

// Group models one consensus group. In production each mutation below is a
// committed log entry; here the seq counter stands in for the log index.
type Group struct {
	Name       string
	Down       bool
	slots      map[uint32]SlotState
	balances   map[string]int64
	applied    map[string]uint32 // idempotency key -> slot of the account it touched
	dirVersion uint64
	seq        uint64
}

func NewGroup(name string) *Group {
	return &Group{
		Name:     name,
		slots:    map[uint32]SlotState{},
		balances: map[string]int64{},
		applied:  map[string]uint32{},
	}
}

// admit checks that this group may accept a write for the account right now:
// the group is up, owns the slot, the slot is not frozen, and the client's
// routing is not behind the directory version this group has learned.
func (g *Group) admit(account string, clientVersion uint64) error {
	if g.Down {
		return ErrUnavailable
	}
	switch g.slots[SlotOf(account)] {
	case Owned:
	case Frozen:
		return ErrFrozen
	default:
		return ErrWrongGroup
	}
	if clientVersion < g.dirVersion {
		return ErrStaleRouting
	}
	return nil
}

// Apply adds delta to an account. A negative delta is a debit. The key makes
// retries safe: a repeated key changes nothing and returns success.
func (g *Group) Apply(key, account string, delta int64, clientVersion uint64) error {
	if err := g.admit(account, clientVersion); err != nil {
		return err
	}
	if _, done := g.applied[key]; done {
		return nil
	}
	if g.balances[account]+delta < 0 {
		return ErrInsufficient
	}
	g.balances[account] += delta
	g.applied[key] = SlotOf(account)
	g.seq++
	return nil
}

// Freeze stops writes to a slot and returns the fence: the sequence number
// that bounds what the copy must contain.
func (g *Group) Freeze(slot uint32) (uint64, error) {
	if g.slots[slot] != Owned {
		return 0, ErrWrongGroup
	}
	g.slots[slot] = Frozen
	g.seq++
	return g.seq, nil
}

// Import copies a frozen slot from src. It refuses if src has changed since
// the fence, because the copy would then be missing committed writes.
func (g *Group) Import(src *Group, slot uint32, fence uint64) error {
	if src.slots[slot] != Frozen || src.seq != fence {
		return ErrMoved
	}
	for acct, bal := range src.balances {
		if SlotOf(acct) == slot {
			g.balances[acct] = bal
		}
	}
	for key, s := range src.applied {
		if s == slot {
			g.applied[key] = s
		}
	}
	return nil
}

// Digest hashes the balances in a slot in a fixed order, so two groups that
// hold the same state produce the same digest.
func (g *Group) Digest(slot uint32) string {
	var accts []string
	for a := range g.balances {
		if SlotOf(a) == slot {
			accts = append(accts, a)
		}
	}
	sort.Strings(accts)
	h := sha256.New()
	for _, a := range accts {
		fmt.Fprintf(h, "%s=%d;", a, g.balances[a])
	}
	return hex.EncodeToString(h.Sum(nil))
}

// Own makes this group the owner of a slot at a directory version.
func (g *Group) Own(slot uint32, version uint64) {
	g.slots[slot] = Owned
	g.observe(version)
	g.seq++
}

// Release gives up a slot. Writes are refused from now on.
func (g *Group) Release(slot uint32, version uint64) {
	delete(g.slots, slot)
	g.observe(version)
	g.seq++
}

func (g *Group) observe(version uint64) {
	if version > g.dirVersion {
		g.dirVersion = version
	}
}

// Move runs the four-stage handoff. Any failure before the directory change
// leaves the source frozen and the directory unchanged.
func Move(src, dst *Group, slot uint32, dir *Directory) error {
	fence, err := src.Freeze(slot)
	if err != nil {
		return err
	}
	if err := dst.Import(src, slot, fence); err != nil {
		return err
	}
	if dst.Digest(slot) != src.Digest(slot) {
		return ErrDigestMismatch
	}
	dir.Version++
	dir.Owner[slot] = dst.Name
	dst.Own(slot, dir.Version)
	src.Release(slot, dir.Version)
	return nil
}

// Client routes by a cached copy of the directory and refreshes on refusal.
type Client struct {
	dir     *Directory
	groups  map[string]*Group
	version uint64
	owner   [SlotCount]string
}

func NewClient(dir *Directory, groups ...*Group) *Client {
	c := &Client{dir: dir, groups: map[string]*Group{}}
	for _, g := range groups {
		c.groups[g.Name] = g
	}
	c.Refresh()
	return c
}

func (c *Client) Refresh() {
	c.version = c.dir.Version
	c.owner = c.dir.Owner
}

// Apply routes by the cached directory. On a routing refusal it refreshes and
// retries under the same key, so a retry can never apply the change twice.
func (c *Client) Apply(key, account string, delta int64) error {
	var err error
	for attempt := 0; attempt < 3; attempt++ {
		g := c.groups[c.owner[SlotOf(account)]]
		if g == nil {
			return ErrWrongGroup
		}
		err = g.Apply(key, account, delta, c.version)
		switch err {
		case ErrWrongGroup, ErrStaleRouting, ErrFrozen, ErrUnavailable:
			c.Refresh()
			continue
		}
		return err
	}
	return err
}

// Transfer is a two-step saga across groups. The debit commits first, the
// credit follows under its own key, and a failed credit is compensated.
func (c *Client) Transfer(key, from, to string, amount int64) error {
	if err := c.Apply(key+"/debit", from, -amount); err != nil {
		return err
	}
	if err := c.Apply(key+"/credit", to, amount); err != nil {
		if cerr := c.Apply(key+"/comp", from, amount); cerr != nil {
			return fmt.Errorf("compensation pending for %s: %w", key, cerr)
		}
		return err
	}
	return nil
}
```

## sharding_test.go

```go
// sharding_test.go
package kestrel

import (
	"errors"
	"fmt"
	"testing"
)

// setup gives G1 every slot at directory version 1.
func setup(t *testing.T) (*Directory, *Group, *Group) {
	t.Helper()
	g1, g2 := NewGroup("G1"), NewGroup("G2")
	dir := &Directory{Version: 1}
	for s := range dir.Owner {
		dir.Owner[s] = "G1"
		g1.slots[uint32(s)] = Owned
	}
	g1.observe(1)
	return dir, g1, g2
}

// An accepted debit survives a move, a stale client is refreshed, and a
// retry under the original key does not apply twice.
func TestMovePreservesAcceptedDebit(t *testing.T) {
	dir, g1, g2 := setup(t)
	c := NewClient(dir, g1, g2)
	acct := "M-2041a"
	g1.balances[acct] = 500

	if err := c.Apply("pay-1", acct, -200); err != nil {
		t.Fatal(err)
	}
	if err := Move(g1, g2, SlotOf(acct), dir); err != nil {
		t.Fatal(err)
	}

	// The client still holds directory version 1. It is refused by G1,
	// refreshes, and succeeds on G2.
	if err := c.Apply("pay-2", acct, -50); err != nil {
		t.Fatalf("apply after move: %v", err)
	}
	if g2.balances[acct] != 250 {
		t.Fatalf("G2 balance = %d, want 250", g2.balances[acct])
	}

	// A client that still believes version 1 is refused by G2.
	if err := g2.Apply("pay-3", acct, -10, 1); !errors.Is(err, ErrStaleRouting) {
		t.Fatalf("stale client on G2: err=%v, want ErrStaleRouting", err)
	}

	// A retry of the original payment is recognized and changes nothing.
	if err := c.Apply("pay-1", acct, -200); err != nil {
		t.Fatalf("retry of pay-1: %v", err)
	}
	if g2.balances[acct] != 250 {
		t.Fatalf("retry changed balance to %d, want 250", g2.balances[acct])
	}
}

// A frozen slot refuses writes, so the copy's contents are fixed.
func TestFrozenSlotRefusesWrites(t *testing.T) {
	_, g1, _ := setup(t)
	acct := "M-2041a"
	g1.balances[acct] = 500
	if _, err := g1.Freeze(SlotOf(acct)); err != nil {
		t.Fatal(err)
	}
	if err := g1.Apply("pay-9", acct, -1, 1); err != ErrFrozen {
		t.Fatalf("write to frozen slot: err=%v, want ErrFrozen", err)
	}
}

// If the source commits anything after the fence, the import refuses,
// because the copy would be missing that write.
func TestImportRejectsSourceChangedAfterFence(t *testing.T) {
	_, g1, g2 := setup(t)
	acct := "M-2041a"
	slot := SlotOf(acct)
	fence, err := g1.Freeze(slot)
	if err != nil {
		t.Fatal(err)
	}
	g1.seq++ // simulate a committed write that bypassed the freeze
	if err := g2.Import(g1, slot, fence); err != ErrMoved {
		t.Fatalf("import after change: err=%v, want ErrMoved", err)
	}
}

// If the credit cannot commit, the saga returns the debited funds.
func TestTransferCompensatesFailedCredit(t *testing.T) {
	dir, g1, g2 := setup(t)
	from := "M-2041a"
	var to string
	for i := 0; ; i++ {
		cand := fmt.Sprintf("C-%d", i)
		if SlotOf(cand) != SlotOf(from) {
			to = cand
			break
		}
	}
	g1.balances[from] = 500

	// Move the destination's slot to G2 so the credit must cross groups.
	toSlot := SlotOf(to)
	if err := Move(g1, g2, toSlot, dir); err != nil {
		t.Fatal(err)
	}
	c := NewClient(dir, g1, g2)
	g2.Down = true

	if err := c.Transfer("tx-1", from, to, 100); err == nil {
		t.Fatal("transfer with unavailable credit succeeded")
	}
	if g1.balances[from] != 500 {
		t.Fatalf("source balance = %d after compensation, want 500", g1.balances[from])
	}
	if g2.balances[to] != 0 {
		t.Fatalf("destination balance = %d, want 0", g2.balances[to])
	}
}
